window.KH_SURA(46, {"sura": "الأحقاف", "n": 46, "ayat": {"1": "حم", "2": "تَنْزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ", "3": "مَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُسَمًّى وَالَّذِينَ كَفَرُوا عَمَّا أُنْذِرُوا مُعْرِضُونَ", "4": "قُلْ أَرَأَيْتُمْ مَا تَدْعُونَ مِنْ دُونِ اللَّهِ أَرُونِي مَاذَا خَلَقُوا مِنَ الْأَرْضِ أَمْ لَهُمْ شِرْكٌ فِي السَّمَاوَاتِ ائْتُونِي بِكِتَابٍ مِنْ قَبْلِ هَذَا أَوْ أَثَارَةٍ مِنْ عِلْمٍ إِنْ كُنْتُمْ صَادِقِينَ", "5": "وَمَنْ أَضَلُّ مِمَّنْ يَدْعُو مِنْ دُونِ اللَّهِ مَنْ لَا يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَامَةِ وَهُمْ عَنْ دُعَائِهِمْ غَافِلُونَ", "6": "وَإِذَا حُشِرَ النَّاسُ كَانُوا لَهُمْ أَعْدَاءً وَكَانُوا بِعِبَادَتِهِمْ كَافِرِينَ", "7": "وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا لِلْحَقِّ لَمَّا جَاءَهُمْ هَذَا سِحْرٌ مُبِينٌ", "8": "أَمْ يَقُولُونَ افْتَرَاهُ قُلْ إِنِ افْتَرَيْتُهُ فَلَا تَمْلِكُونَ لِي مِنَ اللَّهِ شَيْئًا هُوَ أَعْلَمُ بِمَا تُفِيضُونَ فِيهِ كَفَى بِهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَهُوَ الْغَفُورُ الرَّحِيمُ", "9": "قُلْ مَا كُنْتُ بِدْعًا مِنَ الرُّسُلِ وَمَا أَدْرِي مَا يُفْعَلُ بِي وَلَا بِكُمْ إِنْ أَتَّبِعُ إِلَّا مَا يُوحَى إِلَيَّ وَمَا أَنَا إِلَّا نَذِيرٌ مُبِينٌ", "10": "قُلْ أَرَأَيْتُمْ إِنْ كَانَ مِنْ عِنْدِ اللَّهِ وَكَفَرْتُمْ بِهِ وَشَهِدَ شَاهِدٌ مِنْ بَنِي إِسْرَائِيلَ عَلَى مِثْلِهِ فَآمَنَ وَاسْتَكْبَرْتُمْ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ", "11": "وَقَالَ الَّذِينَ كَفَرُوا لِلَّذِينَ آمَنُوا لَوْ كَانَ خَيْرًا مَا سَبَقُونَا إِلَيْهِ وَإِذْ لَمْ يَهْتَدُوا بِهِ فَسَيَقُولُونَ هَذَا إِفْكٌ قَدِيمٌ", "12": "وَمِنْ قَبْلِهِ كِتَابُ مُوسَى إِمَامًا وَرَحْمَةً وَهَذَا كِتَابٌ مُصَدِّقٌ لِسَانًا عَرَبِيًّا لِيُنْذِرَ الَّذِينَ ظَلَمُوا وَبُشْرَى لِلْمُحْسِنِينَ", "13": "إِنَّ الَّذِينَ قَالُوا رَبُّنَا اللَّهُ ثُمَّ اسْتَقَامُوا فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", "14": "أُولَئِكَ أَصْحَابُ الْجَنَّةِ خَالِدِينَ فِيهَا جَزَاءً بِمَا كَانُوا يَعْمَلُونَ", "15": "وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ إِحْسَانًا حَمَلَتْهُ أُمُّهُ كُرْهًا وَوَضَعَتْهُ كُرْهًا وَحَمْلُهُ وَفِصَالُهُ ثَلَاثُونَ شَهْرًا حَتَّى إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً قَالَ رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَى وَالِدَيَّ وَأَنْ أَعْمَلَ صَالِحًا تَرْضَاهُ وَأَصْلِحْ لِي فِي ذُرِّيَّتِي إِنِّي تُبْتُ إِلَيْكَ وَإِنِّي مِنَ الْمُسْلِمِينَ", "16": "أُولَئِكَ الَّذِينَ نَتَقَبَّلُ عَنْهُمْ أَحْسَنَ مَا عَمِلُوا وَنَتَجَاوَزُ عَنْ سَيِّئَاتِهِمْ فِي أَصْحَابِ الْجَنَّةِ وَعْدَ الصِّدْقِ الَّذِي كَانُوا يُوعَدُونَ", "17": "وَالَّذِي قَالَ لِوَالِدَيْهِ أُفٍّ لَكُمَا أَتَعِدَانِنِي أَنْ أُخْرَجَ وَقَدْ خَلَتِ الْقُرُونُ مِنْ قَبْلِي وَهُمَا يَسْتَغِيثَانِ اللَّهَ وَيْلَكَ آمِنْ إِنَّ وَعْدَ اللَّهِ حَقٌّ فَيَقُولُ مَا هَذَا إِلَّا أَسَاطِيرُ الْأَوَّلِينَ", "18": "أُولَئِكَ الَّذِينَ حَقَّ عَلَيْهِمُ الْقَوْلُ فِي أُمَمٍ قَدْ خَلَتْ مِنْ قَبْلِهِمْ مِنَ الْجِنِّ وَالْإِنْسِ إِنَّهُمْ كَانُوا خَاسِرِينَ", "19": "وَلِكُلٍّ دَرَجَاتٌ مِمَّا عَمِلُوا وَلِيُوَفِّيَهُمْ أَعْمَالَهُمْ وَهُمْ لَا يُظْلَمُونَ", "20": "وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَذْهَبْتُمْ طَيِّبَاتِكُمْ فِي حَيَاتِكُمُ الدُّنْيَا وَاسْتَمْتَعْتُمْ بِهَا فَالْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنْتُمْ تَسْتَكْبِرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَبِمَا كُنْتُمْ تَفْسُقُونَ", "21": "وَاذْكُرْ أَخَا عَادٍ إِذْ أَنْذَرَ قَوْمَهُ بِالْأَحْقَافِ وَقَدْ خَلَتِ النُّذُرُ مِنْ بَيْنِ يَدَيْهِ وَمِنْ خَلْفِهِ أَلَّا تَعْبُدُوا إِلَّا اللَّهَ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ", "22": "قَالُوا أَجِئْتَنَا لِتَأْفِكَنَا عَنْ آلِهَتِنَا فَأْتِنَا بِمَا تَعِدُنَا إِنْ كُنْتَ مِنَ الصَّادِقِينَ", "23": "قَالَ إِنَّمَا الْعِلْمُ عِنْدَ اللَّهِ وَأُبَلِّغُكُمْ مَا أُرْسِلْتُ بِهِ وَلَكِنِّي أَرَاكُمْ قَوْمًا تَجْهَلُونَ", "24": "فَلَمَّا رَأَوْهُ عَارِضًا مُسْتَقْبِلَ أَوْدِيَتِهِمْ قَالُوا هَذَا عَارِضٌ مُمْطِرُنَا بَلْ هُوَ مَا اسْتَعْجَلْتُمْ بِهِ رِيحٌ فِيهَا عَذَابٌ أَلِيمٌ", "25": "تُدَمِّرُ كُلَّ شَيْءٍ بِأَمْرِ رَبِّهَا فَأَصْبَحُوا لَا يُرَى إِلَّا مَسَاكِنُهُمْ كَذَلِكَ نَجْزِي الْقَوْمَ الْمُجْرِمِينَ", "26": "وَلَقَدْ مَكَّنَّاهُمْ فِيمَا إِنْ مَكَّنَّاكُمْ فِيهِ وَجَعَلْنَا لَهُمْ سَمْعًا وَأَبْصَارًا وَأَفْئِدَةً فَمَا أَغْنَى عَنْهُمْ سَمْعُهُمْ وَلَا أَبْصَارُهُمْ وَلَا أَفْئِدَتُهُمْ مِنْ شَيْءٍ إِذْ كَانُوا يَجْحَدُونَ بِآيَاتِ اللَّهِ وَحَاقَ بِهِمْ مَا كَانُوا بِهِ يَسْتَهْزِئُونَ", "27": "وَلَقَدْ أَهْلَكْنَا مَا حَوْلَكُمْ مِنَ الْقُرَى وَصَرَّفْنَا الْآيَاتِ لَعَلَّهُمْ يَرْجِعُونَ", "28": "فَلَوْلَا نَصَرَهُمُ الَّذِينَ اتَّخَذُوا مِنْ دُونِ اللَّهِ قُرْبَانًا آلِهَةً بَلْ ضَلُّوا عَنْهُمْ وَذَلِكَ إِفْكُهُمْ وَمَا كَانُوا يَفْتَرُونَ", "29": "وَإِذْ صَرَفْنَا إِلَيْكَ نَفَرًا مِنَ الْجِنِّ يَسْتَمِعُونَ الْقُرْآنَ فَلَمَّا حَضَرُوهُ قَالُوا أَنْصِتُوا فَلَمَّا قُضِيَ وَلَّوْا إِلَى قَوْمِهِمْ مُنْذِرِينَ", "30": "قَالُوا يَاقَوْمَنَا إِنَّا سَمِعْنَا كِتَابًا أُنْزِلَ مِنْ بَعْدِ مُوسَى مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ يَهْدِي إِلَى الْحَقِّ وَإِلَى طَرِيقٍ مُسْتَقِيمٍ", "31": "يَاقَوْمَنَا أَجِيبُوا دَاعِيَ اللَّهِ وَآمِنُوا بِهِ يَغْفِرْ لَكُمْ مِنْ ذُنُوبِكُمْ وَيُجِرْكُمْ مِنْ عَذَابٍ أَلِيمٍ", "32": "وَمَنْ لَا يُجِبْ دَاعِيَ اللَّهِ فَلَيْسَ بِمُعْجِزٍ فِي الْأَرْضِ وَلَيْسَ لَهُ مِنْ دُونِهِ أَوْلِيَاءُ أُولَئِكَ فِي ضَلَالٍ مُبِينٍ", "33": "أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَلَمْ يَعْيَ بِخَلْقِهِنَّ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى بَلَى إِنَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ", "34": "وَيَوْمَ يُعْرَضُ الَّذِينَ كَفَرُوا عَلَى النَّارِ أَلَيْسَ هَذَا بِالْحَقِّ قَالُوا بَلَى وَرَبِّنَا قَالَ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُونَ", "35": "فَاصْبِرْ كَمَا صَبَرَ أُولُو الْعَزْمِ مِنَ الرُّسُلِ وَلَا تَسْتَعْجِلْ لَهُمْ كَأَنَّهُمْ يَوْمَ يَرَوْنَ مَا يُوعَدُونَ لَمْ يَلْبَثُوا إِلَّا سَاعَةً مِنْ نَهَارٍ بَلَاغٌ فَهَلْ يُهْلَكُ إِلَّا الْقَوْمُ الْفَاسِقُونَ"}, "units": [{"aya": 4, "title": "في تأويلها", "tabari": {"page": "21/113", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: الأثارة البقية من علم؛ لأن ذلك هو المعروف من كلام العرب، وهو مصدر من قول القائل: أثر الشيء أثارة، مثل: سمج سماجة، وقبح قباحة، كما قال راعى الإبل :", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: أو ائتوني بعلم بأن آلهتكم خلقت من الأرض شيئا، وأن لها شركا في السماوات، من قبل الخط الذي تخطونه في الأرض ، فإنكم معشر العرب أهل عيافة وزجر وكهانة", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"]], "athar": [70382, 70385, 70386, 70387, 70388]}, {"n": 2, "t": "بل معنى ذلك: أو خاصة من علم", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"]], "athar": [70395]}, {"n": 3, "t": "بل معنى ذلك: أو علم تثيرونه فتستخرجونه", "taqdim": 0, "n_athar": 1, "qailun": [["الحسن", "تابعي"]], "athar": [70394]}, {"n": 4, "t": "بل معنى ذلك: أو تأثرون ذلك علما عن أحد ممن قبلكم", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [70389]}, {"n": 5, "t": "بل معنى ذلك: أو ببينة من الأمر", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [70382, 70385, 70386, 70387, 70388]}, {"n": 6, "t": "بل معنى ذلك: ببقية من علم", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5962, "mi": 1, "aya": 4, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 115 - 116", "qawl": "الأخير الذي", "nass": "لأن ذلك هو المعروف من كلام العرب، وهي مصدر من قول القائل: أثر الشيء أثارة، مثل سمج سماجة", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5962, "mi": 1, "aya": 4, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 7 - 8", "qawl": "", "nass": "وكل هذه الأقوال متقاربة المعنى، وهي راجعة إلى ما قلنا", "qawaid": [], "tabi": ""}, {"taliq": 5962, "mi": 1, "aya": 4, "alam": "ابن تيمية", "fil": "جمع", "kind": "توجيه", "ref": "5/ 547", "qawl": "", "nass": "والأثارة كما قال من قال من السلف: هي الرواية والإسناد. وقالوا: هي الخط أيضا. إذ الرواية والإسناد يكتب بالخط؛ وذلك لأن الأثارة من الأثر، فالعلم الذي يقوله من يقبل قوله يؤثر بالإسناد، ويقيد بالخط؛ فيكون كل ذلك من آثاره", "qawaid": [], "tabi": ""}], "mushid": {"i": 1, "imgs": ["046_001_1.png"], "pages": [468], "n": 6, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5962, "masala": "المراد بقوله: {أثارة من علم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "الخط، ويتضمن أمرين: حسن الكتابة، والقيافة في الأرض", "ashab": "", "athar": []}, {"n": 2, "t": "خاصة من علم", "ashab": "", "athar": []}, {"n": 3, "t": "علم تثيرونه فتستخرجونه", "ashab": "", "athar": []}, {"n": 4, "t": "تأثرون ذلك علما عن أحد ممن قبلكم", "ashab": "", "athar": []}, {"n": 5, "t": "بينة من الأمر", "ashab": "", "athar": []}, {"n": 6, "t": "الإسناد", "ashab": "", "athar": []}, {"n": 7, "t": "بقية من علم", "ashab": "", "athar": []}]}, "tags": {"m": {"7": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 5, "title": "تأويل: ﴿وهم عن دعائهم غافلون﴾", "tabari": {"page": "21/117", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وهم عن دعائهم غافلون﴾. يقول تعالى ذكره: وآلهتهم التي يدعونهم عن دعائهم إياهم في غفلة؛ لأنها لا تسمع ولا تنطق، ولا تعقل. وإنما عنى بوصفها بالغفلة، تمثيلها بالإنسان الساهي عما يقال له، إذ كانت لا تفهم مما يقال لها شيئا، كما لا يفهم الغافل عن الشيء ما غفل عنه. وإنما هذا توبيخ من الله لهؤلاء المشركين لسوء رأيهم، وقبح اختيارهم في عبادتهم من لا يعقل شيئا ولا يفهم، وتركهم عبادة من جميع ما بهم من نعمته، ", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿من لا يستجيب له﴾. فأخرج ذكر الآلهة وهى جماد مخرج ذكر بنى آدم ومن له الاختيار والتمييز، إذ كانت قد مثلتها عبدتها بالملوك والأمراء التي تخدم في خدمتهم إياها، فأجرى الكلام في ذلك على نحو ما كان جاريا فيه عندهم", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 8, "title": "قوله: {فيه} يحتمل", "mawsua": {"taliq": 5964, "masala": "قوله: {فيه} يحتمل", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يعود على القرآن", "ashab": "", "athar": []}, {"n": 2, "t": "أن يعود على {ما}", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5964, "mi": 1, "aya": 8, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 612", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 9, "title": "في تأويله", "tabari": {"page": "21/120", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصحة وأشبهها بما دل عليه التنزيل، القول الذي قاله الحسن البصري، الذي رواه عنه أبو بكر الهذلي.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "عنى به رسول الله ﷺ. وقيل له: قل للمؤمنين بك: ما أدرى ما يفعل بي ولا بكم يوم القيامة، وإلى ما نصير هنالك. قالوا: ثم بين الله لنبيه محمد ﷺ وللمؤمنين به حالهم في الآخرة، فقيل له: ﴿إنا فتحنا لك فتحا مبينا (١) ليغفر لك الله ما تقدم من ذنبك وما تأخر﴾ [الفتح: ١، ٢]. وقال: ﴿ليدخل المؤمنين والمؤمنات جنات تجري من تحتها الأنهار خالدين فيها ويكفر عنهم سيئاتهم﴾ [الفتح: ٥]", "taqdim": 0, "n_athar": 4, "qailun": [["ابن عباس", "صحابي"], ["عكرمة والحسن البصري", "تابعي"], ["قتادة", "تابعي"]], "athar": [70415, 70417, 70419, 70420, 70421, 70425, 70426, 70430, 70437]}, {"n": 2, "t": "بل ذلك أمر من الله جل ثناؤه نبيه ﵊ أن يقوله للمشركين من قومه، ويعلم أنه لا يدرى إلام يصير أمره وأمرهم في الدنيا؛ أيصير أمره معهم أن يقتلوه أو يخرجوه من بينهم، أو يؤمنوا به فيتبعوه، وأمرهم إلى الهلاك كما أهلكت الأمم المكذبة رسلها من قبلهم، أو إلى التصديق له فيما جاءهم به من عند الله", "taqdim": 0, "n_athar": 1, "qailun": [["الحسن", "تابعي"]], "athar": [70422, 70423, 70433]}, {"n": 3, "t": "بل معنى ذلك: وما أدرى ما يفترض علي وعليكم، أو ينزل من حكم. وليس يعني: ما أدرى ما يفعل بي ولا بكم غدا في المعاد، من ثواب الله من أطاعه، وعقابه من كذبه", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 4, "t": "إنما أمر أن يقول هذا في أمر كان ينتظره من قبل الله ﷿ في غير الثواب والعقاب", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [{"taliq": 5966, "mi": 1, "aya": 9, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 123 - 124", "qawl": "الأخير الذي", "nass": "لأن الخطاب من مبتدأ هذه السورة إلى هذه الآية، والخبر خرج من الله عز وجل خطابا للمشركين، وخبرا عنهم، وتوبيخا لهم، واحتجاجا من الله -تعالى ذكره- لنبيه صلى الله عليه وسلم؛ فإذا كان ذلك كذلك فمعلوم أن هذه الآية أيضا سبيلها سبيل ما قبلها وما بعدها في أنها احتجاج عليهم، وتوبيخ لهم، أو خبر عنهم. وإذا كان ذلك كذلك فمحال أن يقال للنبي صلى الله عليه وسلم: قل للمشركين: ما أدري ما يفعل بي ولا بكم في الآخرة. وآيات كتاب الله عز وجل في تنزيله ووحيه إليه متتابعة بأن المشركين في النار مخلدون، والمؤمنون به في الجنان منعمون، وبذلك يرهبهم مرة، ويرغبهم أخرى، ولو قال لهم ذلك لقالوا له: فعلام نتبعك إذن وأنت لا تدري إلى أي حال تصير غدا في القيامة؛ إلى خفض ودعة، أم إلى شدة وعذاب! وإنما اتباعنا إياك إن اتبعناك، وتصديقنا بما تدعونا إليه، رغبة في نعمة، وكرامة نصيبها، أو رهبة من عقوبة، وعذاب نهرب منه", "qawaid": ["السياق", "الدلالة العقلية"], "tabi": ""}, {"taliq": 5966, "mi": 1, "aya": 9, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 9", "qawl": "الأخير بقوله", "nass": "هذا القول هو الذي عول عليه ابن جرير، وأنه لا يجوز غيره، ولا شك أن هذا هو اللائق به صلى الله عليه وسلم؛ فإنه بالنسبة إلى الآخرة جازم أنه يصير إلى الجنة هو ومن اتبعه، وأما في الدنيا فلم يدر ما كان يؤول إليه أمره وأمر مشركي قريش إلى ماذا: أيؤمنون أم يكفرون، فيعذبون فيستأصلون بكفرهم؟", "qawaid": [], "tabi": ""}], "mushid": {"i": 2, "imgs": ["046_002_1.png", "046_002_2.png"], "pages": [468, 469], "n": 4, "rajih": [2], "daif": [], "match": true}, "mawsua": {"taliq": 5966, "masala": "قوله: {ما أدري ما يفعل بي ولا بكم}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن المعنى: في الآخرة، وكان هذا في صدر الإسلام، ثم بعد ذلك عرفه الله تعالى بأنه قد غفر له ما تقدم من ذنبه وما تأخر، وبأن المؤمنين لهم من الله فضل كبير وهو الجنة، وبأن الكافرين في نار جهنم", "ashab": "", "athar": []}, {"n": 2, "t": "أنه صلى الله عليه وسلم أمر أن يقول هذا في أمر كان ينتظره من الله في غير الثواب والعقاب", "ashab": "", "athar": []}, {"n": 3, "t": "أن معنى الآية: لا أدري ما أؤمر به، ولا ما تؤمرون به", "ashab": "", "athar": []}, {"n": 4, "t": "أن المعنى: ما أدري ما يفعل بي ولا بكم في الدنيا من أن أنصر عليكم أو من أن تمكنوا مني", "ashab": "", "athar": []}]}, "tags": {"m": {"4": [["ابن جرير", "r"]]}, "t": {"3": [["ابن جرير", "r"]], "2": [["ابن جرير", "r"]]}, "gen": [], "rules": {"ابن جرير": ["السياق", "الدلالة العقلية"]}, "rulesD": {}}}, {"aya": 10, "title": "المراد بالشاهد، وبحسب هذا اختلف في مكية السورة ومدنيتها", "mawsua": {"taliq": 5968, "masala": "المراد بالشاهد، وبحسب هذا اختلف في مكية السورة ومدنيتها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الآية مدنية، والشاهد عبد الله بن سلام. وقوله: {على مثله} الضمير فيه عائد على قول محمد صلى الله عليه وسلم في القرآن: إنه من عند الله", "ashab": "", "athar": []}, {"n": 2, "t": "أنه رجل من بني إسرائيل غير عبد الله بن سلام كان بمكة، والآية مكية", "ashab": "", "athar": []}, {"n": 3, "t": "الآية مكية، والشاهد عبد الله بن سلام", "ashab": "", "athar": []}, {"n": 4, "t": "أن الشاهد موسى بن عمران، والآية مكية", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5968, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 715", "qawl": "الأخير الذي", "nass": "قوله تعالى: {على مثله} يريد بالمثل: التوراة، والضمير عائد -على هذا التأويل- على القرآن، أي: جاء شاهد من بني إسرائيل بمثله، وشهد أنه من عند الله تعالى", "qawaid": [], "tabi": ""}, {"taliq": 5968, "mi": 1, "aya": 10, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 131", "qawl": "الأخير من", "nass": "لأن قوله: {قل أرأيتم إن كان من عند الله وكفرتم به وشهد شاهد من بني إسرائيل على مثله} في سياق توبيخ الله -تعالى ذكره- مشركي قريش، واحتجاجا عليهم لنبيه صلى الله عليه وسلم، وهذه الآية نظيرة سائر الآيات قبلها، ولم يجر لأهل الكتاب ولا لليهود قبل ذلك ذكر فتوجه هذه الآية إلى أنها فيهم نزلت، ولا دل على انصراف الكلام عن قصص الذين تقدم الخبر عنهم معنى", "qawaid": ["أقوال السلف", "سبب النزول وأحواله", "غير ذلك"], "tabi": ""}, {"taliq": 5968, "mi": 1, "aya": 10, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "13/ 11", "qawl": "", "nass": "فإن هذه الآية مكية نزلت قبل إسلام عبد الله بن سلام، وهذه كقوله: {وإذا يتلى عليهم قالوا آمنا به إنه الحق من ربنا إنا كنا من قبله مسلمين} [القصص: 53]، وقال: {إن الذين أوتوا العلم من قبله إذا يتلى عليهم يخرون للأذقان سجدا ويقولون سبحان ربنا إن كان وعد ربنا لمفعولا} [الإسراء: 107 - 108]", "qawaid": ["سبب النزول وأحواله", "القرآن والنظائر"], "tabi": ""}, {"taliq": 5968, "mi": 1, "aya": 10, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "5/ 95 ط: دار الكتب العلمية", "qawl": "", "nass": "قوله: {فآمن} -على هذا التأويل [يعني: قول مسروق]- يعني به: تصديق موسى بأمر محمد، وتبشيره به. فذلك إيمان به، وأما من قال: الشاهد عبد الله بن سلام، فإيمان بين، وكذلك إيمان الإسرائيلي الذي كان بمكة في قول من قاله", "qawaid": [], "tabi": ""}], "tags": {"m": {"4": [["ابن جرير", "r"]]}, "t": {}, "gen": [["ابن كثير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["أقوال السلف", "سبب النزول وأحواله", "غير ذلك"], "ابن كثير": ["سبب النزول وأحواله", "القرآن والنظائر"]}, "rulesD": {}}}, {"aya": 12, "title": "سبب نزول: ﴿ومن قبله كتب موسى إماما ورحمة وهذا كتاب مصدق لسانا عربيا لينذر الذين ظلموا وبشرى للمحسنين﴾", "tabari": {"page": "21/134", "sarih": 0, "tarjih": "والصواب من القول في ذلك عندى أن يكون منصوبا على أنه حال مما في ﴿مصدق﴾ من ذكر الكتاب؛ لأن قوله: ﴿مصدق﴾ فعل، فتأويل الكلام إذ كان ذلك كذلك: وهذا القرآن يصدق كتاب موسى بأن محمدا نبي مرسل، لسانا عربيا.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ومن قبل هذا الكتاب ﴿كتاب موسى﴾، وهو التوراة، ﴿إماما﴾ لبنى إسرائيل، يأتمون به، ﴿ورحمة﴾ لهم أنزلناه عليهم، وخرج الكلام مخرج الخبر عن الكتاب بغير ذكر تمام الخبر، اكتفاء بدلالة الكلام على تمامه، وتمامه: ومن قبله كتاب موسى إماما ورحمة أنزلناه عليه، وهذا كتاب أنزلناه لسانا عربيا.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "قوله: ﴿لسانا عربيا﴾، من نعت \"الكتاب\"، وإنما نصب لأنه أريد به: وهذا كتاب يصدق التوراة والإنجيل لسانا عربيا، فخرج ﴿لسانا عربيا﴾ من \"يصدق\"؛ لأنه فعل، كما تقول: مررت برجل يقوم محسنا، ومررت برجل قائم محسنا، قال: ولو رفع \"لسان عربي\"، جاز على النعت ل \"الكتاب\"", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 3, "imgs": ["046_003_1.png"], "pages": [469], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "في مبلغ حد ذلك من السنين", "tabari": {"page": "21/138", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "هو ثلاث وثلاثون سنة", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"]], "athar": [70484, 70485, 70491, 70493, 70500, 70501, 70502, 70504, 70509, 70513, 70514, 70518]}, {"n": 2, "t": "هو بلوغ الحلم", "taqdim": 0, "n_athar": 1, "qailun": [["الشعبي", "تابعي"]], "athar": [70503]}]}, "mawaqif": [{"taliq": 5976, "mi": 1, "aya": 15, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 139 - 140", "qawl": "الأخير الذي", "nass": "وإذا كان ذلك كذلك، كان الثلاث والثلاثون به أشبه من الحلم؛ لأن المرء لا يبلغ في حال حلمه كمال قواه، ونهاية شدته، فإن العرب إذا ذكرت مثل هذا من الكلام، فعطفت بعضا على بعض، جعلت كلا الوقتين قريبا أحدهما من صاحبه، كما قال جل ثناؤه: {إن ربك يعلم أنك تقوم أدنى من ثلثي الليل ونصفه} [المزمل: 20]. ولا تكاد تقول: أنا أعلم أنك تقوم قريبا من ساعة من الليل وكله، ولا أخذت قليلا من مال أو كله. ولكن تقول: أخذت عامة مالي أو كله، فكذلك ذلك في قوله: {حتى إذا بلغ أشده وبلغ أربعين سنة}. لا شك أن نسق الأربعين على الثلاث والثلاثين أحسن وأشبه، إذ كان يراد بذلك تقريب أحدهما من الآخر، من النسق على الخمس عشرة أو الثمان عشرة", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5976, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 619", "qawl": "", "nass": "ومن قال بالأربعين قال: إنه في الآية أكد وفسر الأشد بقوله سبحانه: {وبلغ أربعين سنة}", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 4, "imgs": ["046_004_1.png"], "pages": [469], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5976, "masala": "الأشد", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "بلوغ الحلم", "ashab": "", "athar": []}, {"n": 2, "t": "ثمانية عشر عاما", "ashab": "", "athar": []}, {"n": 3, "t": "ثلاثة وثلاثون عاما", "ashab": "", "athar": []}]}, "tags": {"m": {"3": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 15, "title": "قراءة قوله: {وفصاله}", "mawsua": {"taliq": 5972, "masala": "قراءة قوله: {وفصاله}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{وفصاله}", "ashab": "", "athar": []}, {"n": 2, "t": "وفصله", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5972, "mi": 1, "aya": 15, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 138", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5972, "mi": 1, "aya": 15, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 618", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5972, "mi": 1, "aya": 15, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 138", "qawl": "", "nass": "والصواب من القول في ذلك عندنا ما عليه قراء الأمصار؛ لإجماع الحجة من القراء عليه، وشذوذ ما خالفه", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 15, "title": "الأشد", "mawsua": {"taliq": 5976, "masala": "الأشد", "sigha": "زاد قولين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أنه أربعون عاما", "ashab": "", "athar": []}, {"n": 2, "t": "أن الأشد ستة وثلاثين عاما، ورجحه بقوله: «وأقوى الأقوال ستة وثلاثون»، ولم يذكر مستندا", "ashab": "", "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 15, "title": "قوله: {أوزعني}", "mawsua": {"taliq": 5977, "masala": "قوله: {أوزعني}", "sigha": "احتمالات", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "ادفعني عن الموانع، وازجرني عن القواطع؛ لأجل أن أشكر نعمتك", "ashab": "", "athar": []}, {"n": 2, "t": "أن يكون بمعنى: اجعل حظي ونصيبي", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5977, "mi": 0, "aya": 15, "alam": "ابن جرير", "fil": "استدرك", "kind": "نقد", "ref": "21/ 141", "qawl": "ابن زيد", "nass": "وهذا الذي قاله ابن زيد في قوله: {رب أوزعني} وإن كان يؤول إليه معنى الكلمة، فليس بمعنى الإيزاع على الصحة", "qawaid": [], "tabi": ""}, {"taliq": 5977, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 619 - 620", "qawl": "", "nass": "وهذا من التوزيع، والقوم الأوزاع، ومن قولك: توزعوا المال؛ ف {أن} على هذا مفعول صريح", "qawaid": [], "tabi": ""}, {"taliq": 5977, "mi": 1, "aya": 15, "alam": "ابن القيم", "fil": "ذكر", "kind": "نقل", "ref": "2/ 450", "qawl": "بأن معنى", "nass": "ولهذا يقال في تفسير الموزع: المولع، ومنه الحديث: «كان رسول الله صلى الله عليه وسلم موزعا بالسؤال", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 21, "title": "في الموضع الذي به هذه الأحقاف", "tabari": {"page": "21/150", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله ﵎ أخبر أن عادا أنذرهم أخوهم هود بالأحقاف، والأحقاف ما وصفت من الرمال المستطيلة المشرفة، كما قال العجاج :", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "هي جبل بالشام", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"]], "athar": [70569, 70570, 70581]}, {"n": 2, "t": "بل هي واد بين عمان ومهرة", "taqdim": 0, "n_athar": 2, "qailun": [["ابن عباس", "صحابي"], ["ابن إسحاق", "تابع التابعين"]], "athar": [70569, 70570, 70579, 70581]}, {"n": 3, "t": "هي أرض", "taqdim": 0, "n_athar": 3, "qailun": [["مجاهد", "تابعي"], ["ابن أبي نجيح", "تابع التابعين"]], "athar": [70571, 70572, 70573, 70582]}, {"n": 4, "t": "هي رمال مشرفة على البحر بالشحر", "taqdim": 0, "n_athar": 3, "qailun": [["قتادة", "تابعي"]], "athar": [70575]}]}, "mawaqif": [{"taliq": 5983, "mi": 1, "aya": 21, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 153 بتصرف", "qawl": "", "nass": "وأولى الأقوال في ذلك بالصواب أن يقال: إن الله تبارك وتعالى أخبر أن عادا أنذرهم أخوهم هود بالأحقاف، والأحقاف: الرمال المستطيلة المشرفة … وجائز أن يكون ذلك جبلا بالشام، وجائز أن يكون واديا بين عمان وحضرموت، وجائز أن يكون الشحر. وليس في العلم به أداء فرض، ولا في الجهل به تضييع واجب، وأين كان فصفته ما وصفنا من أنهم كانوا قوما منازلهم الرمال المستعلية المستطيلة", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5983, "mi": 1, "aya": 21, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 625", "qawl": "بأنها كانت", "nass": "والصحيح من الأقوال: أن بلاد عاد كانت في اليمن، ولهم إرم ذات العماد", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "mushid": {"i": 5, "imgs": ["046_005_1.png"], "pages": [469], "n": 4, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5983, "masala": "الأحقاف ومكان وجودها", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "جبل بالشام", "ashab": "", "athar": []}, {"n": 2, "t": "أنها أرض", "ashab": "", "athar": []}, {"n": 3, "t": "رمال مشرفة على البحر بالشحر", "ashab": "", "athar": []}, {"n": 4, "t": "واد بين عمان ومهرة", "ashab": "", "athar": []}, {"n": 5, "t": "هي بين حضرموت وعمان", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"], ["ابن عطية", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة"], "ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 24, "title": "قوله: {رأوه} يحتمل", "mawsua": {"taliq": 5984, "masala": "قوله: {رأوه} يحتمل", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يعود على العذاب", "ashab": "", "athar": []}, {"n": 2, "t": "أن يعود على الشيء المرئي الطالع عليهم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5984, "mi": 1, "aya": 24, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 626", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 25, "title": "قراءة قوله: {فأصبحوا لا يرى إلا مساكنهم}", "mawsua": {"taliq": 5985, "masala": "قراءة قوله: {فأصبحوا لا يرى إلا مساكنهم}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{لا يرى إلا مساكنهم}", "ashab": "", "athar": []}, {"n": 2, "t": "(لا ترى إلا مساكنهم)", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5985, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 158 - 159", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5985, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 627", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5985, "mi": 1, "aya": 25, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 159", "qawl": "", "nass": "وبأي القراءتين اللتين ذكرت قرأ ذلك القارئ فمصيب، وهو القراءة برفع المساكن إذا قرئ قوله: {يرى} بالياء وضمها. وبنصب المساكن إذا قرئ قوله: {ترى} بالتاء وفتحها", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5985, "mi": 1, "aya": 25, "alam": "ابن عطية", "fil": "انتقدها", "kind": "نقد", "ref": "7/ 628", "qawl": "", "nass": "وفي هذه القراءة استكراه", "qawaid": [], "tabi": "ابن جرير"}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 28, "title": "قراءة قوله: {وذلك إفكهم}", "mawsua": {"taliq": 5987, "masala": "قراءة قوله: {وذلك إفكهم}", "sigha": "حكاية خلاف", "nasib": "", "aqwal": [{"n": 1, "t": "{وذلك إفكهم} بكسر الألف وسكون الفاء وضم الكاف", "ashab": "", "athar": []}, {"n": 2, "t": "بفتح الألف والكاف", "ashab": "", "athar": []}, {"n": 3, "t": "(أفكهم) بفتح الألف وتشديد الفاء", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5987, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 163", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5987, "mi": 1, "aya": 28, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 630", "qawl": "", "nass": "ذلك", "qawaid": [], "tabi": ""}, {"taliq": 5987, "mi": 1, "aya": 28, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "21/ 163", "qawl": "", "nass": "والصواب من القراءة في ذلك عندنا القراءة التي عليها قرأة الأمصار؛ لإجماع الحجة عليها", "qawaid": ["القراءة ورسم المصحف"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن جرير": ["القراءة ورسم المصحف"]}, "rulesD": {}}}, {"aya": 29, "title": "في مبلغ عدد النفر الذين قال الله: ﴿وإذ صرفنا إليك نفرا من الجن﴾", "tabari": {"page": "21/164", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "كانوا سبعة نفر", "taqdim": 0, "n_athar": 1, "qailun": [["ابن عباس", "صحابي"]], "athar": [70629, 70630, 70631, 70632, 70644]}, {"n": 2, "t": "بل كانوا تسعة نفر", "taqdim": 0, "n_athar": 2, "qailun": [["زر", "تابعي"], ["زر بن حبيش", "تابعي"]], "athar": [70633, 70634, 70645]}]}, "mawaqif": [], "mushid": {"i": 6, "imgs": ["046_006_1.png"], "pages": [470], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 29, "title": "في صفة حضورهم كان رسول الله ﷺ", "tabari": {"page": "21/166", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "حضروا رسول الله ﷺ يتعرفون الأمر الذي حدث من قبله ما حدث في السماء، ورسول الله ﷺ لا يشعر بمكانهم، كما قد ذكرنا عن ابن عباس قبل", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل أمر نبي الله ﷺ أن يقرأ عليهم القرآن، وأنما جمعوا له بعد أن تقدم الله إليه بإنذارهم، وأمره بقراءة القرآن عليهم", "taqdim": 0, "n_athar": 5, "qailun": [["قتادة", "تابعي"], ["ابن شهاب", "تابع التابعين"]], "athar": [70640, 70647]}]}, "mawaqif": [{"taliq": 5993, "mi": 0, "aya": 29, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 171", "qawl": "", "nass": "وهذا القول خلاف القول الذي روي عنه -المذكور في تفسير الآية من طريق العوفي- أنه قال: لم يكن نبي الله صلى الله عليه وسلم علم أنهم استمعوا إليه وهو يقرأ القرآن؛ لأنه محال أن يرسلهم إلى آخرين إلا بعد علمه بمكانهم. إلا أن يقال: لم يعلم بمكانهم في حال استماعهم للقرآن، ثم علم بعد قبل انصرافهم إلى قومهم، فأرسلهم رسلا حينئذ إلى قومهم، وليس ذلك في الخبر الذي روي", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["046_007_1.png"], "pages": [470], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 33, "title": "في وجه دخول الباء في قوله: ﴿بقادر﴾", "tabari": {"page": "21/174", "sarih": 1, "tarjih": "وأشبه الأقوال في ذلك بالصواب قول من قال: دخلت الباء في قوله: بقدر للجحد؛ لما ذكرنا لقائلي ذلك من العلل.", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "هذه الباء كالباء في قوله: ﴿وكفى بالله﴾ [الرعد: ٤٣، الإسراء: ٩٦، العنكبوت: ٥٢]. وهو مثل: ﴿تنبت بالدهن﴾ [المؤمنون: ٢٠]", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "دخلت هذه الباء ل \"لم\". قال والعرب تدخلها مع الجحود إذا كانت رافعة لما قبلها، وتدخلها إذا وقع عليها فعل يحتاج إلى اسمين، مثل قولك: ما أظنك بقائم، وما أظن أنك بقائم، وما كنت بقائم. فإذا خلعت الباء نصبت الذي كانت تعمل فيه [بما يعمل فيه] من الفعل. قال: ولو ألقيت الباء من \"قادر\" في هذا الموضع رفع؛ لأنه خبر ل \"أن\". قال: وأنشدني بعضهم:", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 3, "t": "هذه الباء دخلت للجحد؛ لأن المجحود في المعنى - وإن كان قد حال بينهما ب \"أن\" -: أو لم يروا أن الله قادر على أن يحيي الموتى. قال: ف \"أن\" اسم \"يروا\"، وما بعدها في صلتها، ولا تدخل فيه الباء، ولكن معناه جحد، فدخلت للمعنى", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 8, "imgs": ["046_008_1.png"], "pages": [470], "n": 2, "rajih": [], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 35, "title": "تأويل: ﴿فاصبر كما صبر أولو العزم من الرسل ولا تستعجل لهم كأنهم يوم يرون ما يوعدون لم يلبثوا إلا سا﴾", "tabari": {"page": "21/177", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره لنبيه محمد ﷺ، مثبته على المضي لما قلده من عبء الرسالة وثقل أحمال النبوة ﷺ، وآمره بالائتساء في العزم على النفوذ لذلك بأولى العزم من قبله من رسله الذين صبروا على عظيم ما لقوا فيه من قومهم من المكاره، ونالهم فيه منهم من الأذى والشدائد: ﴿فاصبر﴾ يا محمد على ما أصابك في الله من أذى مكذبيك من قومك الذين أرسلناك إليهم بالإنذار، ﴿كما صبر أولو العزم﴾ على القيام بأمر الله، والانتهاء إلى طاعته", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "إن أولى العزم منهم كانوا الذين امتحنوا في ذات الله في الدنيا بالمحن، فلم تزدهم المحن إلا جدا في أمر الله، كنوح وإبراهيم وموسى ومن أشبههم", "taqdim": 0, "n_athar": 3, "qailun": [["عطاء الخراساني", "تابعي"], ["قتادة", "تابعي"], ["سعيد بن جبير", "تابعي"]], "athar": [70678, 70687, 70688, 70689, 70690, 70697]}]}, "mawaqif": [], "mushid": {"i": 9, "imgs": ["046_009_1.png"], "pages": [470], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [], "others": {"0": [{"id": 5957, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 608): «هذه السورة مكية لم يُختلف منها إلا في آيتين، وهي قوله: {قُلْ أرَأَيْتُمْ إنْ كانَ مِن عِنْدِ اللَّهِ وكَفَرْتُمْ بِهِ وشَهِدَ شاهِدٌ مِن بَنِي إسْرائِيلَ عَلى مِثْلِهِ فَآمَنَ واسْتَكْبَرْتُمْ} [10]، وقوله: {فاصْبِرْ كَما صَبَرَ أُولُوا العَزْمِ مِنَ الرُّسُلِ} الآية [35]، فقال بعض المفسرين: هاتان آيتان مدنيتان وُضعتا في سورة مكية».", "mawaqif": [{"taliq": 5957, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 608", "qawl": "", "nass": "هذه السورة مكية لم يختلف منها إلا في آيتين، وهي قوله: {قل أرأيتم إن كان من عند الله وكفرتم به وشهد شاهد من بني إسرائيل على مثله فآمن واستكبرتم} [10]، وقوله: {فاصبر كما صبر أولوا العزم من الرسل} الآية [35]، فقال بعض المفسرين: هاتان آيتان مدنيتان وضعتا في سورة مكية", "qawaid": [], "tabi": ""}]}], "4": [{"id": 5958, "kinds": "توجيه،تعليق،نقل", "text": "علَّق ابنُ عطية (7/ 609 - 610) على هذا القول الذي قاله ابن عباس، وأبو سلمة من طريق صفوان، وأبو بكر بن عياش، فقال: «وذلك شيء كانت العرب تفعله وتتكهّن به وتزجر، وهذا مِن البقية والأثر، وروي أن النبي صلى الله عليه وسلم سئل عن ذلك فقال: «كان نبي من الأنبياء يخطّه، فمن وافق خطَّه فذاك»». وذكر في تأويل الحديث وجهين: الأول: ظاهر الحديث يقوي أمر الخطّ في التراب، وأنه شيء له وجه إذا وفق أحد إليه. وهكذا تأوّله كثير من العلماء. الثاني: أن معناه: الإنكار، أي: أنه كان مِن فعل نبيٍّ قد ذهب، وذهب الوحي إليه والإلهام في ذلك، ثم قال: «فمن وافق خطّه» على جهة الإبعاد، أي: أنّ ذلك لا يمكن مِمَّن ليس بنبي ميسّر لذلك، وهذا كما يسألك أحد فيقول: أيطير الإنسان؟ فتقول: إنما يطير الطائر، فمَن كان له مِن الناس جناحان طار. أي: أن ذلك لا يكون.", "mawaqif": [{"taliq": 5958, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 609 - 610", "qawl": "", "nass": "وذلك شيء كانت العرب تفعله وتتكهن به وتزجر، وهذا من البقية والأثر، وروي أن النبي صلى الله عليه وسلم سئل عن ذلك فقال: «كان نبي من الأنبياء يخطه، فمن وافق خطه فذاك»", "qawaid": [], "tabi": ""}]}, {"id": 5959, "kinds": "نقل", "text": "ذكر ابنُ كثير (13/ 6) أن هذا القول على قراءة من قرأ: «أثَرَةٍ».\nوبنحوه قال ابنُ جرير (21/ 115).", "mawaqif": [{"taliq": 5959, "mi": 0, "aya": 4, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 6", "qawl": "على قراءة", "nass": "أثرة", "qawaid": [], "tabi": ""}, {"taliq": 5959, "mi": 0, "aya": 4, "alam": "ابن جرير", "fil": "قال", "kind": "قول", "ref": "21/ 115", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن كثير"}]}, {"id": 5960, "kinds": "تعليق", "text": "علَّق ابنُ عطية (7/ 609) على هذا القول الذي قاله قتادة، وميمون، وأبو سلمة، بقوله: «فاشتقاقها من الأَثرة، كأنها قد آثر الله بها مَن هي عنده».", "mawaqif": [{"taliq": 5960, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 609", "qawl": "", "nass": "فاشتقاقها من الأثرة، كأنها قد آثر الله بها من هي عنده", "qawaid": [], "tabi": ""}]}, {"id": 5961, "kinds": "بيان،تعليق،نقل", "text": "ساق ابنُ عطية (7/ 609) قول القرظي، ثم علَّق بقوله: \"ومن هذا المعنى قول الأعشى:\nإن الذي فيه تماريتما بيّن للسامع والآثر\nأي: وللمسند عن غيره، ومنه قول عمر?: فما خلّفت بها ذاكرًا ولا آثرًا\".", "mawaqif": [{"taliq": 5961, "mi": 0, "aya": 4, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 609", "qawl": "القرظي", "nass": "", "qawaid": [], "tabi": ""}]}], "5": [{"id": 5963, "kinds": "نقل", "text": "على هذا القول فالضمير في قوله: {عن دعائهم} عائد على الأصنام، وهو ما ذكر ابنُ عطية (7/ 609)، ثم ساق احتمالًا آخر، فقال: «ويحتمل أن يكون الضمير في قوله: {عن دعائهم غافلون} للكفار، أي: ضلالهم بأنهم يدعون مَن لا يستجيب، فلا يتأملون ما عليهم في دعائهم مَن هذه صفته».", "mawaqif": [{"taliq": 5963, "mi": 0, "aya": 5, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 609", "qawl": "", "nass": "ويحتمل أن يكون الضمير في قوله: {عن دعائهم غافلون} للكفار، أي: ضلالهم بأنهم يدعون من لا يستجيب، فلا يتأملون ما عليهم في دعائهم من هذه صفته", "qawaid": [], "tabi": ""}]}], "9": [{"id": 5965, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 613) أن ما جاء في حديث عثمان بن مظعون الوارد في الآثار المتعلقة بالآية يُؤَيِّد هذا القول الذي قاله ابن عباس، وأنس، وعكرمة، وقتادة، والحسن، ومقاتل، وهو قوله: «فواللهِ، ما أدري وأنا رسول الله ما يُفعل بي». وبيّن أنه على الرواية التي تقول: «ما يُفعل به» فلا حجة للقول في الحديث. ثم علَّق بقوله: «والمعنى عندي في هذا القول: أنه لم تُكشف له الخاتمة، فقال: «لا أدري». وأمّا من وافى على الإيمان فقد أُعلِم بنجاته مِن أول الرسالة، وإلا فكان للكفار أن يقولوا: وكيف تدعونا إلى ما لا تدري له عاقبة؟».", "mawaqif": [{"taliq": 5965, "mi": 0, "aya": 9, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 613", "qawl": "", "nass": "فوالله، ما أدري وأنا رسول الله ما يفعل بي", "qawaid": [], "tabi": ""}]}], "10": [{"id": 5967, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 615) أن الآية على هذا القول -الذي قاله مجاهد، وعطاء، وعكرمة- من الآيات التي تضمنت غيبًا أبرزه الوجود، ثم قال: «وقد روي عن عبد الله بن سلام أنه قال: فِيّ نزلت».", "mawaqif": [{"taliq": 5967, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 615", "qawl": "", "nass": "وقد روي عن عبد الله بن سلام أنه قال: في نزلت", "qawaid": [], "tabi": ""}]}], "11": [{"id": 5969, "kinds": "نقل", "text": "على قول قتادة فالكلام معنيٌّ به: قريش. وذكر ابنُ جرير (21/ 132) أنّ تفسيره هذا فيه تركٌ منه لما قاله في الشاهد في الآية السابقة من أنّه ابن سلام.", "mawaqif": [{"taliq": 5969, "mi": 0, "aya": 11, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 132", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5970, "kinds": "بيان،نقل", "text": "ذكر ابنُ جرير (21/ 132) أنّ مَن فسر الشاهد في الآية السابقة بابن سلام فالكلام في الآية من يهود بني إسرائيل للمؤمنين، ومَن فسره بأنه معني به مشركو قريش فالكلام لمشركي قريش.", "mawaqif": [{"taliq": 5970, "mi": 0, "aya": 11, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "21/ 132", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "13": [{"id": 5971, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 616) أنّ كثيرًا مِن الناس ذهب إلى أن معنى الآية: ثم اسْتَقامُوا بالطاعات والأعمال الصالحات. وساق قول أبي بكر، ثم علَّق عليه بقوله: «وهذا القول أعمّ رجاءً وأوسع، وإن كان في الجملة المؤمنة مَن يُعذب وينفذ عليه الوعيد، فهو ممن يُخلّد في الجنة وينتفي عنه الخوف والحزن الحالّ بالكفرة».", "mawaqif": [{"taliq": 5971, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 616", "qawl": "أبي بكر", "nass": "وهذا القول أعم رجاء وأوسع، وإن كان في الجملة المؤمنة من يعذب وينفذ عليه الوعيد، فهو ممن يخلد في الجنة وينتفي عنه الخوف والحزن الحال بالكفرة", "qawaid": [], "tabi": ""}]}], "15": [{"id": 5973, "kinds": "ترجيح،نقد،توجيه", "text": "انتقد ابنُ عطية (5/ 98 ط: دار الكتب العلمية) القول بنزولها في أبي بكر الذي قاله علي، وابن عباس، ومقاتل مستندًا لأحوال النزول، فقال: «وفي هذا القول اعتراض بأنّ هذه الآية نزلت بمكة لا خلاف في ذلك، وأبو قحافة أسلم عام الفتح». ثم وجّهه (7/ 620) بقوله: «فإنما يتجه هذا التأويل على أنّ أبا بكر كان يطمع بإيمان أبويه، ويرى مخايل ذلك فيهما، فكانت هذه نعمة عليهما، أن ليسا مِمَّن عَسى في الكفر ولجّ وحُتم عليه، ثم ظهر إيمانهما بعد».\nثم رجَّح (7/ 620 - 621 بتصرف) العموم مستندًا إلى ظاهر لفظ الآية، فقال: «والقول بأنها عامة في نوع الإنسان لم يقصد بها أبو بكر ولا غيره أصح، وقوله تعالى: {أُولئِكَ} دليل على أن الإشارة بقوله: {ووَصَّيْنا الإنْسانَ} إنما أراد الجنس».", "mawaqif": [{"taliq": 5973, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "5/ 98 ط: دار الكتب العلمية", "qawl": "بنزولها في", "nass": "وفي هذا القول اعتراض بأن هذه الآية نزلت بمكة لا خلاف في ذلك، وأبو قحافة أسلم عام الفتح", "qawaid": ["سبب النزول وأحواله", "ظاهر الآية ولفظها"], "tabi": ""}]}, {"id": 5974, "kinds": "خلاف،ترجيح،نقل", "text": "اختُلف في قراءة قوله: {كرها}؛ فقرأ قوم بضم الكاف، وقرأ غيرهم بفتحها.\nوذكر ابنُ عطية (7/ 618) أنهما بمعنى واحد. ثم ساق هذا القول، ونقل أنّ فرقة قالت: الكُره -بالضم-: المشقّة. والكَره -بالفتح-: هو الغلبة والقهر. وذكر أنهم ضعّفوا -على هذا- قراءة الفتح، وأنهم قالوا: لو كان كَرهًا لرمت به عن نفسها؛ إذ الكَره: القهر والغلبة. ثم رجَّح القول الأول، فقال: «والقول الذي قدّمناه أصوب». ولم يذكر مستندًا.", "mawaqif": [{"taliq": 5974, "mi": 0, "aya": 15, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 618", "qawl": "الأول", "nass": "والقول الذي قدمناه أصوب", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5975, "kinds": "ترجيح،تعليق", "text": "علَّق ابنُ كثير (13/ 14) على ما استنبطه علي بن أبي طالب مِن أنّ أقل مُدّة الحمْل ستة أشهر، بقوله: «وهو استنباط قوي صحيح، ووافقه عليه عثمان، وجماعة من الصحابة».", "mawaqif": [{"taliq": 5975, "mi": 0, "aya": 15, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 14", "qawl": "", "nass": "وهو استنباط قوي صحيح، ووافقه عليه عثمان، وجماعة من الصحابة", "qawaid": [], "tabi": ""}]}], "16": [{"id": 5978, "kinds": "تعليق،نقل", "text": "علَّق ابنُ كثير (13/ 17) على هذا الحديث، بقوله: «هكذا رواه ابن أبي حاتم، عن أبيه، عن محمد بن عبد الأعلى الصنعاني، عن المعتمر بن سليمان، بإسناده مثله -وزاد عن الروح الأمين-. قال: قال الرّب جل جلاله: «يؤتى بحسنات العبد وسيئاته … » فذكره».", "mawaqif": [{"taliq": 5978, "mi": 0, "aya": 16, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 17", "qawl": "", "nass": "هكذا رواه ابن أبي حاتم، عن أبيه، عن محمد بن عبد الأعلى الصنعاني، عن المعتمر بن سليمان، بإسناده مثله -وزاد عن الروح الأمين-. قال: قال الرب جل جلاله: «يؤتى بحسنات العبد وسيئاته …", "qawaid": [], "tabi": ""}]}], "17": [{"id": 5979, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 622) أن ابن عبد البر قال بأن الذي كان يخطب هو معاوية، وانتقده بقوله: «وهذا وهْم».", "mawaqif": [{"taliq": 5979, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 622", "qawl": "", "nass": "وهذا وهم", "qawaid": [], "tabi": ""}]}, {"id": 5980, "kinds": "ترجيح،نقد،نقل", "text": "على هذا القول الذي قاله الحسن، وقتادة، فالآية عامة كالتي قبلها، وهو ما ذكره ابنُ عطية (7/ 621)، ثم قال: «ويشبه أن لها سببًا من رجل قال ذلك لأبويه. فلمّا فرغ من ذكر الموفق عقّب بذكر هذا العاق».\nورجَّح (7/ 622) العموم، وانتقد القول بنزولها في ابن أبي بكر مستندًا للسياق، فقال: «والأصوب أن تكون عامة في أهل هذه الصفات، ولم يقصد بها عبد الرحمن ولا غيره من المؤمنين، والدليل القاطع على ذلك قوله: {أُولئِكَ الَّذِينَ حَقَّ عَلَيْهِمُ القَوْلُ فِي أُمَمٍ}، وكان عبد الرحمن? من أفضل الصحابة، ومن الأبطال، وممن له في الإسلام غَناءٌ، ويكفيه مقامه مع مروان يوم اليمامة وغيره».\nوبنحوه قال ابنُ كثير (13/ 18).\nثم قال ابنُ عطية (7/ 623): «وظاهر ألفاظ هذه الآية أنها نزلت في مُشار إليه قال وقيل له، فنعى الله أقواله تحذيرًا مِن الوقوع في مثلها».", "mawaqif": [{"taliq": 5980, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "ذكره", "kind": "نقل", "ref": "7/ 621", "qawl": "", "nass": "ويشبه أن لها سببا من رجل قال ذلك لأبويه. فلما فرغ من ذكر الموفق عقب بذكر هذا العاق", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5980, "mi": 0, "aya": 17, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 18", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 5980, "mi": 0, "aya": 17, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 623", "qawl": "", "nass": "وظاهر ألفاظ هذه الآية أنها نزلت في مشار إليه قال وقيل له، فنعى الله أقواله تحذيرا من الوقوع في مثلها", "qawaid": [], "tabi": ""}]}], "18": [{"id": 5981, "kinds": "نقد", "text": "انتقد ابنُ عطية (7/ 623) قول الحسن مستندًا لظاهر الآية، والسنة، فقال: «قوله: {قد خلت من قبلهم من الجن والإنس} يقتضي أن الجن يموتون كما يموت البشر قرنًا بعد قرن، وقد جاء حديث يقتضي ذلك».", "mawaqif": [{"taliq": 5981, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "انتقد", "kind": "نقد", "ref": "7/ 623", "qawl": "الحسن مستندا", "nass": "قوله: {قد خلت من قبلهم من الجن والإنس} يقتضي أن الجن يموتون كما يموت البشر قرنا بعد قرن، وقد جاء حديث يقتضي ذلك", "qawaid": ["ظاهر الآية ولفظها", "السنة"], "tabi": ""}]}, {"id": 5982, "kinds": "نقل", "text": "ذكر ابنُ عطية (7/ 623) أن قوله: {أولئك} ظاهر أنها إشارة إلى جنس يتضمنه قوله: {والذي قال}.\nوبنحوه قال ابنُ كثير (13/ 20).\nثم قال ابنُ عطية: «ويحتمل -إن كانت الآية في مُشار إليه- أن يكون قوله: {أولئك} بمعنى: صنف هذا المذكور وجنسهم {الذين حقّ عليهم القول} أي: قول الله تعالى».", "mawaqif": [{"taliq": 5982, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 623", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5982, "mi": 0, "aya": 18, "alam": "ابن كثير", "fil": "قال", "kind": "قول", "ref": "13/ 20", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن عطية"}, {"taliq": 5982, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "", "qawl": "", "nass": "ويحتمل -إن كانت الآية في مشار إليه- أن يكون قوله: {أولئك} بمعنى: صنف هذا المذكور وجنسهم {الذين حق عليهم القول} أي: قول الله تعالى", "qawaid": [], "tabi": ""}]}], "26": [{"id": 5986, "kinds": "نقد،نقل", "text": "ذكر ابنُ عطية (7/ 629) أنّ فرقة قالت: {إن} شرطية، والجواب محذوف، تقديره: في الذي إن مكناكم فيه طغيتم. وانتقده بقوله: «وهذا تنطّع في التأويل».", "mawaqif": [{"taliq": 5986, "mi": 0, "aya": 26, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 629", "qawl": "", "nass": "وهذا تنطع في التأويل", "qawaid": [], "tabi": ""}]}], "29": [{"id": 5988, "kinds": "نقد", "text": "انتقد ابنُ كثير (13/ 31) ما جاء في هذا الأثر مِن أنّ استماع الجن كان عند منصرف النبي صلى الله عليه وسلم مِن الطائف مستندًا إلى دلالة التاريخ، فقال: «لأنّ الجنَّ كان استماعهم في ابتداء الإيحاء، كما دلّ عليه حديثُ ابن عباس المذكور في تفسير الآية من طريق العوفي، وخروجه صلى الله عليه وسلم إلى الطائف كان بعد موت عمِّه، وذلك قبل الهجرة بسنة أو سنتين، كما قرره ابن إسحاق وغيره».", "mawaqif": [{"taliq": 5988, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "انتقد", "kind": "نقد", "ref": "13/ 31", "qawl": "", "nass": "لأن الجن كان استماعهم في ابتداء الإيحاء، كما دل عليه حديث ابن عباس المذكور في تفسير الآية من طريق العوفي، وخروجه صلى الله عليه وسلم إلى الطائف كان بعد موت عمه، وذلك قبل الهجرة بسنة أو سنتين، كما قرره ابن إسحاق وغيره", "qawaid": ["التاريخ والواقع"], "tabi": ""}]}, {"id": 5989, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 630): «قوله: {صرفنا} معناه: رددناهم عن حالٍ ما، يحتمل أنها الاستماع في السماء، ويحتمل أن تكون بُعْدهم قبل الوفادة، وهذا بحسب الاختلاف هنا، هل هم الوفد أو المتجسسون؟».", "mawaqif": [{"taliq": 5989, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 630", "qawl": "", "nass": "قوله: {صرفنا} معناه: رددناهم عن حال ما، يحتمل أنها الاستماع في السماء، ويحتمل أن تكون بعدهم قبل الوفادة، وهذا بحسب الاختلاف هنا، هل هم الوفد أو المتجسسون؟", "qawaid": [], "tabi": ""}]}, {"id": 5990, "kinds": "خلاف،ترجيح،توجيه،بيان،تعليق،نقل", "text": "اختُلف هل علم النبي صلى الله عليه وسلم بقدوم الجن عليه أم لا؟ وساق ابنُ عطية (7/ 631) القولين، ثم رجَّح أنّ الوفد الوارد ذكره هنا غير الوفد المشار إليه في سورة الجن، فقال: «والتحرير في هذا أن النبي صلى الله عليه وسلم جاءه جنٌّ دون أن يعرف بهم، وهم المتفرّقون من أجل الرّجم، وهذا هو قوله تعالى: {قل أوحي إلي} [الجن: 1]، ثم بعد ذلك وفد عليه وفد، وهو المذكور صرْفه في هذه الآية». ولم يذكر مستندًا.\nوساق ابنُ كثير (13/ 31 - 32) آثارًا تدل على عدم علم النبي بهم حال قراءته، وبيّن أنّ ما يعارضها مِن آثار تقتضي علمه، فيُحتمل أنه كان في مرة أخرى؛ إذ تكاثر الروايات يدل على تكرار توافد الجن عليه، فقال: «فأما ما رواه البخاري ومسلم جميعًا، [وهو حديث ابن مسعود الآتي في الآثار المتعلقة بالآيات أن شجرة آذنت الني صلى الله عليه وسلم بالجن] فيحتمل أن يكون هذا في المرة الأولى، ويكون إثباتًا مقدمًا على نفي ابن عباس المذكور في تفسير الآية من طريق العوفي، ويحتمل أن يكون هذا في بعض المرات المتأخرات، والله أعلم. ويحتمل أن يكون في الأولى ولكن لم يشعر بهم حال استماعهم حتى آذَنَته بهم الشجرة، أي: أعلمته باستماعهم». وعلَّق (13/ 42) على ما جاء عن ابن مسعود من اختلاف في الروايات بأنه يحتمل الآتي: أنه لم يكن مع رسول الله صلى الله عليه وسلم حال مخاطبته الجنّ ودعائه إياهم، وإنما كان بعيدًا منه، ولم يخرج مع النبي صلى الله عليه وسلم أحد سواه، ومع هذا لم يشهد حال المخاطبة. الثاني: أن يكون أول مرّة خرج إليهم لم يكن معه ابن مسعود ولا غيره، ثم بعد ذلك خرج معه ليلة أخرى.\nوعلَّق ابن عطية (7/ 632) على ما روي عن ابن مسعود بقوله: «واضطربت الروايات عن عبد الله بن مسعود … فاختصرتُ هذه الروايات وتطويلها؛ لعدم صحتها».", "mawaqif": [{"taliq": 5990, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 631", "qawl": "", "nass": "والتحرير في هذا أن النبي صلى الله عليه وسلم جاءه جن دون أن يعرف بهم، وهم المتفرقون من أجل الرجم، وهذا هو قوله تعالى: {قل أوحي إلي} [الجن: 1]، ثم بعد ذلك وفد عليه وفد، وهو المذكور صرفه في هذه الآية", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}, {"taliq": 5990, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "ساق", "kind": "نقل", "ref": "13/ 31 - 32", "qawl": "", "nass": "فأما ما رواه البخاري ومسلم جميعا، [وهو حديث ابن مسعود الآتي في الآثار المتعلقة بالآيات أن شجرة آذنت الني صلى الله عليه وسلم بالجن] فيحتمل أن يكون هذا في المرة الأولى، ويكون إثباتا مقدما على نفي ابن عباس المذكور في تفسير الآية من طريق العوفي، ويحتمل أن يكون هذا في بعض المرات المتأخرات، والله أعلم. ويحتمل أن يكون في الأولى ولكن لم يشعر بهم حال استماعهم حتى آذنته بهم الشجرة، أي: أعلمته باستماعهم", "qawaid": [], "tabi": ""}, {"taliq": 5990, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 632", "qawl": "", "nass": "واضطربت الروايات عن عبد الله بن مسعود … فاختصرت هذه الروايات وتطويلها؛ لعدم صحتها", "qawaid": [], "tabi": ""}]}, {"id": 5991, "kinds": "تعليق", "text": "علَّق ابنُ كثير (13/ 30) على هذا الأثر بقوله: «رواه الترمذي والنسائي في كتابي التفسير من سننيهما، من حديث إسرائيل به، وقال الترمذي: حسن صحيح. وهكذا رواه أيوب عن سعيد بن جبير، عن ابن عباس. وكذا رواه العوفي، عن ابن عباس أيضًا، بمثل هذا السياق بطوله».", "mawaqif": [{"taliq": 5991, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 30", "qawl": "", "nass": "رواه الترمذي والنسائي في كتابي التفسير من سننيهما، من حديث إسرائيل به، وقال الترمذي: حسن صحيح. وهكذا رواه أيوب عن سعيد بن جبير، عن ابن عباس. وكذا رواه العوفي، عن ابن عباس أيضا، بمثل هذا السياق بطوله", "qawaid": [], "tabi": ""}]}, {"id": 5992, "kinds": "خلاف،تعليق،نقل", "text": "علَّق ابنُ عطية (7/ 632) على ما جاء في عدد وفد الجّن، بقوله: «واختُلِف في عددهم اختلافًا مُتباعدًا، فاختصرته؛ لعدم الصحة في ذلك».\nوذكر ابنُ كثير (13/ 44) أن هذا الاختلاف في عددهم يدل على تكرار وفادتهم على النبي صلى الله عليه وسلم.", "mawaqif": [{"taliq": 5992, "mi": 0, "aya": 29, "alam": "ابن عطية", "fil": "علق", "kind": "تعليق", "ref": "7/ 632", "qawl": "", "nass": "واختلف في عددهم اختلافا متباعدا، فاختصرته؛ لعدم الصحة في ذلك", "qawaid": [], "tabi": ""}, {"taliq": 5992, "mi": 0, "aya": 29, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 44", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "30": [{"id": 5994, "kinds": "بيان،تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 633) أنّ ابن عباس قال: لم يكونوا علِموا أمرَ عيسى عليه السلام؛ فلذلك قالوا: مِن بعد موسى. ثم علَّق بقوله: «وقولهم: {مصدقا لما بين يديه} يؤيد هذا».", "mawaqif": [{"taliq": 5994, "mi": 0, "aya": 30, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 633", "qawl": "", "nass": "وقولهم: {مصدقا لما بين يديه} يؤيد هذا", "qawaid": [], "tabi": ""}]}], "32": [{"id": 5995, "kinds": "نقل", "text": "ذكر ابن عطية (7/ 633 - 634) أن قوله تعالى: {ومَن لا يُجِبْ داعِيَ اللَّهِ فَلَيْسَ بِمُعْجِزٍ} الآية، يحتمل أن يكون من كلام المنذرين، ويحتمل أن يكون من كلام الله تعالى لمحمد صلى الله عليه وسلم، والمراد بها إسماع الكفار.", "mawaqif": [{"taliq": 5995, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 633 - 634", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}, {"id": 5996, "kinds": "تعليق،نقل", "text": "علَّق ابنُ كثير (13/ 34 - 35) على هذا الحديث بقوله: «رواه ابن جرير عن محمد بن عبد الله بن عبد الحكم، عن أبي زرعة وهب الله بن راشد، عن يونس بن يزيد الأيلي، به. ورواه البيهقي في الدلائل، من حديث عبد الله بن صالح -كاتب الليث- عن الليث، عن يونس به. وقد روى إسحاق بن راهويه، عن جرير، عن قابوس بن أبي ظبيان، عن أبيه، عن ابن مسعود، فذكر نحو ما تقدم. ورواه الحافظ أبو نعيم، من طريق موسى بن عبيدة، عن سعيد بن الحارث، عن أبي المعلى، عن ابن مسعود فذكر نحوه أيضًا». وذكره (13/ 36) من طريق آخر ووصفه بالغرابة الشديدة.", "mawaqif": [{"taliq": 5996, "mi": 0, "aya": 32, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "13/ 34 - 35", "qawl": "", "nass": "رواه ابن جرير عن محمد بن عبد الله بن عبد الحكم، عن أبي زرعة وهب الله بن راشد، عن يونس بن يزيد الأيلي، به. ورواه البيهقي في الدلائل، من حديث عبد الله بن صالح -كاتب الليث- عن الليث، عن يونس به. وقد روى إسحاق بن راهويه، عن جرير، عن قابوس بن أبي ظبيان، عن أبيه، عن ابن مسعود، فذكر نحو ما تقدم. ورواه الحافظ أبو نعيم، من طريق موسى بن عبيدة، عن سعيد بن الحارث، عن أبي المعلى، عن ابن مسعود فذكر نحوه أيضا", "qawaid": [], "tabi": ""}]}, {"id": 5997, "kinds": "بيان", "text": "بيّن ابن كثير (13/ 49) أن هذه الرواية تدل على وفود الجن على النبي صلى الله عليه وسلم بعد هجرته إلى المدينة.", "mawaqif": [{"taliq": 5997, "mi": 0, "aya": 32, "alam": "ابن كثير", "fil": "بين", "kind": "بيان", "ref": "13/ 49", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}]}], "35": [{"id": 5998, "kinds": "تعليق،نقل", "text": "ساق ابن عطية (7/ 636) قول مقاتل، ثم علَّق بقوله: «وانظر أن النبي صلى الله عليه وسلم قال في موسى: «يرحم الله موسى، أوذي بأكثر من هذا فصبر». ولا محالة أن لكل نبي ورسول عزْمًا وصبرًا -صلى الله عليهم وسلم-».", "mawaqif": [{"taliq": 5998, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ساق", "kind": "نقل", "ref": "7/ 636", "qawl": "مقاتل", "nass": "وانظر أن النبي صلى الله عليه وسلم قال في موسى: «يرحم الله موسى، أوذي بأكثر من هذا فصبر", "qawaid": [], "tabi": ""}]}, {"id": 5999, "kinds": "بيان،نقل", "text": "ذكر ابنُ عطية (7/ 635) أن {من} على قول ابن زيد لبيان الجنس. ثم قال: «ولكن قوله: {كما صبر أولوا العزم} يتضمن رسلًا وغيرهم، فبيّن بعد ذلك جنس الرسل خاصّة تعظيمًا لهم».\nوذكر ابنُ كثير (13/ 56) أنّ أشهر الأقوال في أولي العزم أنهم: نوح، وإبراهيم، وموسى، وعيسى، وخاتم الأنبياء كلّهم محمد صلى الله عليه وسلم، الذين نصّ الله على أسمائهم مِن بين الأنبياء في آيتين من سورتي الأحزاب والشورى، وأنه يحتمل أن يكون المراد بأولي العزم جميع الرسل، وتكون {من} في قوله: {من الرسل} لبيان الجنس، كما هو قول ابن زيد.", "mawaqif": [{"taliq": 5999, "mi": 0, "aya": 35, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 635", "qawl": "ابن زيد", "nass": "ولكن قوله: {كما صبر أولوا العزم} يتضمن رسلا وغيرهم، فبين بعد ذلك جنس الرسل خاصة تعظيما لهم", "qawaid": [], "tabi": ""}, {"taliq": 5999, "mi": 0, "aya": 35, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "13/ 56", "qawl": "ابن زيد", "nass": "", "qawaid": [], "tabi": ""}]}]}, "athar": {"70647": {"num": 70647, "aya": 29, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فَلَمّا حَضَرُوهُ قالُوا أنْصِتُوا}: قد علِم القومُ أنهم لن يعقلوا حتى يُنصِتوا."}, "70415": {"num": 70415, "aya": 9, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق علي- {قُلْ ما كُنْتُ بِدْعًا مِنَ الرُّسُلِ}، يقول: لستُ بأوَّل الرسل."}, "70417": {"num": 70417, "aya": 9, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق معمر- {قُلْ ما كُنْتُ بِدْعًا مِنَ الرُّسُلِ}، قال: يقول: قد كانت الرسل قبله."}, "70419": {"num": 70419, "aya": 9, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق الكلبي، عن أبي صالح-: لَمّا اشتدّ البلاءُ بأصحاب رسول الله صلى الله عليه وسلم رأى في المنام أنّه يُهاجِر إلى أرضٍ ذات نخْل وشجر وماء، فقصّها على أصحابه، فاستبشروا بذلك ورأوا فيها فرَجًا مما هم فيه مِن أذى المشركين، ثم إنهم مكثوا بُرهة لا يرون ذلك، فقالوا: يا رسول الله، متى نهاجر إلى الأرض التي رأيتَ؟ فسكت رسول الله صلى الله عليه وسلم، فأنزل الله تعالى: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ} يعني: لا أدري أخرج إلى الموضع الذي رأيته في منامي أو لا؟ ثم قال: «إنّما هو شيء رأيته في منامي، ما أتَّبِع إلا ما يُوحى إلَيَّ»."}, "70420": {"num": 70420, "aya": 9, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق عطاء-: إنّ اليهود شَتموا النبيَّ صلى الله عليه وسلم والمسلمين لَمّا نزل قوله: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ}، وقالوا: كيف نتبع رجلًا لا يدري ما يُفعَل به؟! فاشتدّ ذلك على النبي صلى الله عليه وسلم؛ فأنزل الله تعالى: {إنّا فَتَحْنا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ ما تَقَدَّمَ مِن ذَنْبِكَ وما تَأَخَّرَ} [الفتح: 1 - 2]."}, "70421": {"num": 70421, "aya": 9, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية، وتفسيرها", "text": "عن عبد الله بن عباس -من طريق علي-: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ} فأنزل الله بعد هذا: {لِيَغْفِرَ لَكَ اللَّهُ ما تَقَدَّمَ مِن ذَنْبِكَ وما تَأَخَّرَ} [الفتح: 2]، وقوله: {لِيُدْخِلَ المُؤْمِنِينَ والمُؤْمِناتِ جَنّاتٍ} [الفتح: 5]؛ فأعلم الله سبحانه نبيّه ما يُفعَل به وبالمؤمنين جميعًا."}, "70422": {"num": 70422, "aya": 9, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن الحسن البصري، قال: لَمّا نزلت هذه الآية: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ} عَمِل رسول الله صلى الله عليه وسلم في الخوف زمانًا، فلما نزلت: {إنّا فَتَحْنا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ ما تَقَدَّمَ مِن ذَنْبِكَ وما تَأَخَّرَ} [الفتح: 1 - 2] اجتهد، فقيل له: تُجهد نفسك وقد غفر اللهُ لك ما تقدّم من ذنبك وما تأخر؟! قال: أفلا أكون عبدًا شكورًا."}, "70423": {"num": 70423, "aya": 9, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن الحسن البصري -من طريق أبي بكر الهُذلي- في قوله: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ} قال: أما في الآخرة فمعاذ الله؛ قد عَلِم أنّه في الجنة حين أخذ ميثاقه في الرسل، ولكن: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ} في الدنيا؛ أُخرَج كما أُخرِجت الأنبياء مِن قبلي، أم أُقتَل كما قُتلَت الأنبياء من قبلي، {ولا بِكُمْ} أُمّتي المكذّبة، أم أُمّتي المصدّقة، أم أُمّتي المرميّة بالحجارة من السماء قذْفًا، أم مخسوف بها خسْفًا. ثم أوحي إليه: {وإذْ قُلْنا لَكَ إنَّ رَبَّكَ أحاطَ بِالنّاسِ} [الإسراء: 60]، يقول: أحطتُ لك بالعرب ألا يقتلوك. فعرف أنه لا يُقتَل، ثم أنزل الله: {هُوَ الَّذِي أرْسَلَ رَسُولَهُ بِالهُدى ودِينِ الحَقِّ لِيُظْهِرَهُ عَلى الدِّينِ كُلِّهِ وكَفى بِاللَّهِ شَهِيدًا} [الفتح: 28]، يقول: أشْهَدَ لك على نفسه أنه سيُظهِر دينك على الأديان. ثم قال له في أمته: {وما كانَ اللَّهُ لِيُعَذِّبَهُمْ وأَنْتَ فِيهِمْ وما كانَ اللَّهُ مُعَذِّبَهُمْ وهُمْ يَسْتَغْفِرُونَ} [الأنفال: 33]. فأخبر الله ما يَصْنع به، وما يَصْنع بأُمّته."}, "70678": {"num": 70678, "aya": 35, "qail": "سعيد بن جبير", "tabaqa": "تابعي", "bab": "", "text": "عن سعيد بن جُبير -من طريق سالم- في قوله: {فاصْبِرْ كَما صَبَرَ أُولُو العَزْمِ مِنَ الرُّسُلِ}، قال: سمّاه الله مِن شدّته: العزْم."}, "70425": {"num": 70425, "aya": 9, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق سعيد- {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ}، قال: ثم دَرى نبي الله صلى الله عليه وسلم بعد ذلك ما يُفعَل به بقوله: {إنّا فَتَحْنا لَكَ فَتْحًا مُبِينًا لِيَغْفِرَ لَكَ اللَّهُ ما تَقَدَّمَ مِن ذَنْبِكَ وما تَأَخَّرَ} [الفتح: 1 - 2]."}, "70426": {"num": 70426, "aya": 9, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "نزول الآية، وتفسيرها", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ}، قال: قد بيّن له أنه قد غُفِر مِن ذنبه ما تقدّم وما تأخّر."}, "70430": {"num": 70430, "aya": 9, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "النسخ في الآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- في الأحقاف: {وما أدْرِي ما يُفْعَلُ بِي ولا بِكُمْ}، قال: نَسَختْها هذه الآية التي في الفتح، فخرج إلى الناس، فبشّرهم بالذي غُفِر له ما تقدّم مِن ذنبه وما تأخر، فقال رجل من المؤمنين: هنيئًا لك، يا نبيَّ الله، قد علِمنا الآن ما يُفعَل بك، فماذا يُفعَل بنا؟ فأنزل الله في الأحزاب: {وبَشِّرِ المُؤْمِنِينَ بِأَنَّ لَهُمْ مِنَ اللَّهِ فَضْلًا كَبِيرًا} [الأحزاب: 47]، وقال: {لِيُدْخِلَ المُؤْمِنِينَ والمُؤْمِناتِ جَنّاتٍ تَجْرِي مِن تَحْتِها الأَنْهارُ خالِدِينَ فِيها ويُكَفِّرَ عَنْهُمْ سَيِّئاتِهِمْ وكانَ ذَلِكَ عِنْدَ اللَّهِ فَوْزًا عَظِيمًا} [الفتح: 5]، فبيّن الله ما يُفعل به وبهم."}, "70687": {"num": 70687, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة، في قوله: {أُولُو العَزْمِ}، قال: هم نوح، وهود، وإبراهيم، وشعيب، وموسى."}, "70688": {"num": 70688, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {فاصْبِرْ كَما صَبَرَ أُولُو العَزْمِ مِنَ الرُّسُلِ}: كُنّا نحدّث: أنّ إبراهيم كان منهم."}, "70433": {"num": 70433, "aya": 9, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "النسخ في الآية", "text": "والحسن البصري -من طريق يزيد-، مثله."}, "70689": {"num": 70689, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- قال: {أُولُو العَزْمِ} نوح، وإبراهيم، وموسى، وعيسى."}, "70690": {"num": 70690, "aya": 35, "qail": "عطاء الخراساني", "tabaqa": "تابعي", "bab": "", "text": "عن عطاء الخُراسانيّ -من طريق ثوابة بن مسعود- أنّه قال: {فاصْبِرْ كَما صَبَرَ أُولُو العَزْمِ مِنَ الرُّسُلِ} نوح، وإبراهيم، وموسى، وعيسى، ومحمد."}, "70437": {"num": 70437, "aya": 9, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: لَمّا مات عثمان بن مظعون قالت امرأته أو امرأةٌ: هنيئًا لك -ابنَ مظعون- الجنة. فنظر إليها رسول الله صلى الله عليه وسلم نظَر مُغضَب، وقال: «وما يدريكِ؟! واللهِ، إنِّي لرسول الله وما أدري ما يُفعل بي». قال: وذلك قبل أن ينزل: {لِيَغْفِرَ لَكَ اللَّهُ ما تَقَدَّمَ مِن ذَنْبِكَ وما تَأَخَّرَ} [الفتح: 2]، فقالت: يا رسول الله، صاحبُك، وفارسُك، وأنت أعلم. فقال: «أرجو له رحمةَ ربِّه، وأخاف عليه ذنبه»."}, "70569": {"num": 70569, "aya": 21, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية- قال: الأحقاف: جبل بالشام."}, "70570": {"num": 70570, "aya": 21, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- {واذْكُرْ أخا عادٍ إذْ أنْذَرَ قَوْمَهُ بِالأَحْقافِ}، قال: الأحقاف الذي أنذر هود قومه: وادٍ بين عُمان ومَهَرة."}, "70571": {"num": 70571, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- قال: الأحقاف: الأرض."}, "70572": {"num": 70572, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: الأحقاف: حِشافٌ من حِسْمى."}, "70573": {"num": 70573, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {بالأَحْقافِ}، قال: تِلال مِن رمْلٍ باليمن."}, "70697": {"num": 70697, "aya": 35, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فَهَلْ يُهْلَكُ إلّا القَوْمُ الفاسِقُونَ}، قال: تعلّموا، واللهِ، ما يَهْلِكُ على الله إلا هالك؛ مشرك ولّى الإسلام ظهره، أو منافق صدّق بلسانه وخالف بعمله."}, "70575": {"num": 70575, "aya": 21, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: ذُكر لنا: أنّ عادًا كانوا أحياء باليمن، أهل رمْلٍ، مشرفين على البحر، بأرض يقال لها: الشِّحْرُ."}, "70579": {"num": 70579, "aya": 21, "qail": "محمد بن إسحاق", "tabaqa": "تابع التابعين", "bab": "", "text": "عن محمد بن إسحاق -من طريق سلمة- قال: كانت منازل عاد وجماعتهم حيث بعث الله إليهم هودًا الأحقاف: الرّمل فيما بين عُمان إلى حضرموت، فاليمن كلّه، وكانوا مع ذلك قد فَشَوا في الأرض كلّها، قهروا أهلها بفضل قوّتهم التي آتاهم الله."}, "70581": {"num": 70581, "aya": 21, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: قال رسول الله صلى الله عليه وسلم: «يرحمنا الله وأخا عاد»."}, "70582": {"num": 70582, "aya": 21, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- {واذكر أخا عاد إذ أنذر قومه بالأحقاف وقد خلت النذر من بين يديه ومن خلفه}: جاءت قبلهم الرسلُ النُّذر بتوحيد الله، وأتى الرسلُ بعدهم بتوحيد الله."}, "70640": {"num": 70640, "aya": 29, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قوله: {وإذْ صَرَفْنا إلَيْكَ نَفَرًا مِنَ الجِنِّ يَسْتَمِعُونَ القُرْآنَ}، قال: ذُكر لنا: أنّهم صُرِفوا إليه مِن نينوى. قال: فإنّ نبي الله صلى الله عليه وسلم قال: «إنِّي أُمِرْتُ أن أقرأ القرآن على الجنّ، فأيكم يتبعني؟». فأطرقوا، ثم استتبعهم، فأطرقوا، ثم استتبعهم الثالثة، فأطرقوا، فقال رجل: يا رسول الله، إنّك لَذو بَدِيئة. فاتّبعه عبد الله بن مسعود، فدخل رسول الله صلى الله عليه وسلم شِعبًا يقال له: شِعب الحَجُون. قال: وخطّ نبيُّ الله صلى الله عليه وسلم على عبد الله خطًّا ليثبته به. قال: فجعلتْ تهوي بي، وأرى أمثال النّسور تمشي في دفوفها، وسمعتُ لغطًا شديدًا، حتى خِفتُ على نبيِّ الله صلى الله عليه وسلم، ثم تلا القرآن؛ فلما رجع نبيُّ الله قلتُ: يا نبي الله، ما اللّغط الذي سمعتُ؟ قال: «اجتمعوا إلَيَّ في قتيلٍ كان بينهم». فقضى بينهم بالحق. ذُكر لنا: أنّ ابنَ مسعود لَمّا قدِم الكوفة رأى شيوخًا شُمْطًا مِن الزُّط، فراعُوه، قال: مَن هؤلاء؟ قالوا: هؤلاء نَفر من الأعاجم. قال: ما أُرِيتُ للذين قرأ عليهم النبي صلى الله عليه وسلم الإسلام مِن الجن شَبَهًا أدنى مِن هؤلاء."}, "70484": {"num": 70484, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، قال: نزلتْ هذه الآية في أبي بكر الصِّدِّيق: {حَتّى إذا بَلَغَ أشُدَّهُ وبَلَغَ أرْبَعِينَ سَنَةً قالَ رَبِّ أوْزِعْنِي} الآية، فاستجاب اللهُ له، فأسلم والداه جميعًا وإخوانه وولده كلّهم، ونزلت فيه أيضًا: {فَأَمّا مَن أعْطى واتَّقى} [الليل: 5] إلى آخر السورة."}, "70485": {"num": 70485, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق الكلبي، عن أبي صالح- قال: نزلتْ في أبي بكر الصِّدِّيق: {ووَصَّيْنا الإنْسانَ بِوالِدَيْهِ إحْسانًا} إلى قوله: {وعْدَ الصِّدْقِ الَّذِي كانُوا يُوعَدُونَ}."}, "70491": {"num": 70491, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- {حَمَلَتْهُ أُمُّهُ كُرْهًا ووَضَعَتْهُ كُرْهًا}، يقول: حمَلتْه مَشقَّة، ووضعَتْه مَشقَّة."}, "70493": {"num": 70493, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- أنه كان يقول: إذا ولدت المرأة لتسعة أشهُر كفاها مِن الرضاع أحد وعشرون شهرًا، وإذا ولدت لسبعة أشهر كفاها من الرضاع ثلاثة وعشرون شهرًا، وإذا وضعت لستة أشهُر فحَوْلين كامِلين؛ لأنّ الله تعالى يقول: {وحَمْلُهُ وفِصالُهُ ثَلاثُونَ شَهْرًا}."}, "70500": {"num": 70500, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: {حَتّى إذا بَلَغَ أشُدَّهُ} نهاية قوّته، وغاية شبابه واستوائه، وهو ما بين ثماني عشرة سنة إلى أربعين سنة، فذلك قوله: {وبَلَغَ أرْبَعِينَ سَنَةً}."}, "70501": {"num": 70501, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق مجاهد- قال: أشدّه: ثلاث وثلاثون سنة، واستواؤه: أربعون سنة، والعُذر الذي أعذر الله فيه إلى ابن آدم: ستُّون."}, "70502": {"num": 70502, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق الكلبي، عن أبي صالح- {حتى إذا بلغ أشده}، قال: ما بين ثماني عشرة إلى ثلاثين سنه، فهو في الشَّدّ."}, "70503": {"num": 70503, "aya": 15, "qail": "عامر الشعبي", "tabaqa": "تابعي", "bab": "", "text": "عن عامر الشعبي -من طريق مجالد- قال: الأشدّ: الحُلُم إذا كُتبت له الحسنات، وكُتبت عليه السيئات."}, "70504": {"num": 70504, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله تعالى: {حَتّى إذا بَلَغَ أشُدَّهُ}: ثلاثًا وثلاثين سنة."}, "70629": {"num": 70629, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق النضر بن عربي، عن عكرمة- {وإذْ صَرَفْنا إلَيْكَ نَفَرًا مِنَ الجِنِّ يَسْتَمِعُونَ القُرْآنَ} الآية، قال: كانوا تسعة نفر مِن أهل نَصيبِين، فجعلهم رسول الله صلى الله عليه وسلم رُسلًا إلى قومهم."}, "70630": {"num": 70630, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق قتادة، عن عكرمة- قال: صُرِفَت الجنُّ إلى رسول الله صلى الله عليه وسلم مرتين، وكان أشراف الجن بنَصيبِين."}, "70631": {"num": 70631, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس-من طريق جابر الجعفي، عن عكرمة- {وإذْ صَرَفْنا إلَيْكَ نَفَرًا مِنَ الجِنِّ}: كانوا من أهل نَصيبِين، أتَوه ببطن نخلة."}, "70632": {"num": 70632, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {وإذْ صَرَفْنا إلَيْكَ نَفَرًا مِنَ الجِنِّ يَسْتَمِعُونَ القُرْآنَ} إلى آخر الآية، قال: لم تكن السماءُ تُحرَس في الفتْرة بين عيسى ومحمد -صلى الله عليهما-، وكانوا يقعدون مقاعد للسمع، فلمّا بعث الله محمدًا صلى الله عليه وسلم حُرِسَت السماء حرَسًا شديدًا، ورُجمت الشياطين، فأنكروا ذلك، وقالوا: {وأَنّا لا نَدْرِي أشَرٌّ أُرِيدَ بِمَن فِي الأَرْضِ أمْ أرادَ بِهِمْ رَبُّهُمْ رَشَدًا} [الجن: 10]. فقال إبليس: لقد حدَث في الأرض حدَثٌ. واجتمعت إليه الجنُّ، فقال: تفرّقوا في الأرض، فأخبِروني ما هذا الخبر الذي حدث في السماء، وكان أول بعْثٍ ركْبٌ مِن أهل نَصيبِين، وهي أشراف الجن وساداتهم، فبعثهم إلى تهامة، فاندفعوا حتى بلغوا الوادي؛ وادي نخلة، فوجدوا نبي الله صلى الله عليه وسلم يصلي صلاة الغَداة ببطن نخلة، فاستمعوا، فلما سمعوه يتلو القرآن قالوا: أنصِتوا. ولم يكن نبيُّ الله صلى الله عليه وسلم عَلِم أنهم استمعوا إليه وهو يقرأ القرآن، {فَلَمّا قُضِيَ ولَّوْا إلى قَوْمِهِمْ مُنْذِرِينَ}..........................................."}, "70509": {"num": 70509, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {وبَلَغَ أرْبَعِينَ سَنَةً}: وقد مضى مِن سيئ عَمَله."}, "70382": {"num": 70382, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس، عن النبيّ صلى الله عليه وسلم: {أوْ أثارَةٍ مِن عِلْمٍ}، قال: «الخَطّ»."}, "70633": {"num": 70633, "aya": 29, "qail": "زر بن حبيش", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن زِرّ بن حُبيْش -من طريق عاصم-: أُنزِل على النبي صلى الله عليه وسلم وهو ببطن نخلة: {فَلَمّا حَضَرُوهُ}، قال: كانوا تسعة، أحدهم زَوْبَعة."}, "70634": {"num": 70634, "aya": 29, "qail": "زر بن حبيش", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن زِرّ بن حُبيْش -من طريق عاصم-: كانوا سبعة، أكبرهم زَوْبَعة."}, "70385": {"num": 70385, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي سلمة- {أوْ أثارَةٍ مِن عِلْمٍ}، قال: هو الخَطّ."}, "70386": {"num": 70386, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي سلمة- في قوله: {أوْ أثارَةٍ مِن عِلْمٍ}، قال: خطٌّ كان يخطّه العرب في الأرض."}, "70387": {"num": 70387, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق الشعبي- {أوْ أثارَةٍ مِن عِلْمٍ}، قال: جَوْدة الخَطّ."}, "70388": {"num": 70388, "aya": 4, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- {أوْ أثارَةٍ مِن عِلْمٍ}، يقول: بيّنة من الأمر."}, "70389": {"num": 70389, "aya": 4, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {أوْ أثارَةٍ مِن عِلْمٍ}، قال: أحد يأثِر علمًا."}, "70513": {"num": 70513, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "قال عبد الله بن عباس: {وأَنْ أعْمَلَ صالِحًا تَرْضاهُ} وأجابه الله عز وجل، فأعتق تسعةً مِن المؤمنين يُعذَّبون في الله، ولم يُرِد شيئًا مِن الخير إلا أعانه الله عليه."}, "70514": {"num": 70514, "aya": 15, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق معمر- في قوله تعالى: {وبَلَغَ أرْبَعِينَ سَنَةً قالَ رَبِّ أوْزِعْنِي أنْ أشْكُرَ نِعْمَتَكَ الَّتِي أنْعَمْتَ عَلَيَّ وعَلى والِدَيَّ} الآية حتى {المُسْلِمِينَ}، قال: وقد مضى مِن سيئ عَمَله ما قد مضى."}, "70518": {"num": 70518, "aya": 15, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق الضَّحّاك- مرفوعًا: «مَن أتى عليه أربعون سنة فلم يَغْلِب خيرُه شرَّه فليتجهّز إلى النار»."}, "70644": {"num": 70644, "aya": 29, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العَوفيّ- في قوله: {فَلَمّا قُضِيَ} يقول: فلما فرغ من الصلاة {ولَّوْا إلى قَوْمِهِمْ مُنْذِرِينَ}."}, "70394": {"num": 70394, "aya": 4, "qail": "الحسن البصري", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن الحسن البصري -من طريق معمر، عمَّن سمعه- {أوْ أثارَةٍ مِن عِلْمٍ}: شيء يستخرجه فيُثِيره."}, "70395": {"num": 70395, "aya": 4, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {أوْ أثارَةٍ مِن عِلْمٍ}، قال: أو خاصّة من علم."}, "70645": {"num": 70645, "aya": 29, "qail": "زر بن حبيش", "tabaqa": "تابعي", "bab": "", "text": "عن زِرّ بن حُبيْش -من طريق عاصم- في قوله: {فَلَمّا حَضَرُوهُ قالُوا أنْصِتُوا}، قالوا: صَه."}}, "n_athar": {"0": 11, "1": 1, "3": 1, "4": 27, "5": 1, "6": 2, "7": 1, "8": 3, "9": 25, "10": 32, "11": 8, "12": 1, "13": 2, "15": 39, "16": 6, "17": 17, "18": 2, "19": 3, "20": 20, "21": 16, "22": 2, "23": 1, "24": 22, "25": 4, "26": 5, "27": 3, "28": 4, "29": 23, "30": 3, "31": 2, "32": 13, "33": 7, "34": 1, "35": 26}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});